define("mod_tarsuszero/dashboard", ['core/ajax', 'core/notification', 'core/str'], function(Ajax, Notification, Str) {

    var SELECTORS = {
        RESOURCE_ROW: '[data-region="tarsus-resource"]',
        ACTION_BUTTON: '[data-action]',
        STATUS_BADGE: '[data-region="status-badge"]',
        STATUS_SPINNER: '[data-region="status-spinner"]',
        INCLUDE_TOGGLE: '[data-region="tarsus-include-toggle"]'
    };

    var BADGE_CLASSES = [
        'badge-light', 'badge-warning', 'badge-secondary', 'badge-success', 'badge-danger'
    ];

    var POLL_INTERVAL = 4000;
    var cmid = 0;
    var pollTimer = null;

    function escapeId(value) {
        if (window.CSS && window.CSS.escape) {
            return window.CSS.escape(value);
        }
        return value.replace(/[!"#$%&'()*+,./:;<=>?@[\]^`{|}~]/g, '\\$&');
    }

    function updateRow(row, data) {
        var badge = row.querySelector(SELECTORS.STATUS_BADGE);
        if (badge) {
            badge.textContent = data.statuslabel;
            BADGE_CLASSES.forEach(function(cls) { badge.classList.remove(cls); });
            badge.classList.add(data.badgeclass);
        }
        var spinner = row.querySelector(SELECTORS.STATUS_SPINNER);
        if (spinner) {
            spinner.hidden = !data.inflight;
        }
        var map = {index: data.canindex, reindex: data.canreindex, remove: data.canremove, retry: data.canretry};
        row.querySelectorAll(SELECTORS.ACTION_BUTTON).forEach(function(button) {
            var action = button.getAttribute('data-action');
            button.hidden = !map[action];
            button.disabled = false;
        });
    }

    function hasInflight(root) {
        return Array.from(root.querySelectorAll(SELECTORS.STATUS_SPINNER))
            .some(function(s) { return !s.hidden; });
    }

    function stopPolling() {
        if (pollTimer !== null) {
            window.clearInterval(pollTimer);
            pollTimer = null;
        }
    }

    function poll(root) {
        Ajax.call([{methodname: 'mod_tarsuszero_get_index_status', args: {cmid: cmid}}])[0]
            .then(function(response) {
                response.resources.forEach(function(data) {
                    var row = root.querySelector(
                        SELECTORS.RESOURCE_ROW + '[data-resourceid="' + escapeId(data.resourceid) + '"]'
                    );
                    if (row) { updateRow(row, data); }
                });
                if (!hasInflight(root)) { stopPolling(); }
                return response;
            }).catch(Notification.exception);
    }

    function startPolling(root) {
        if (pollTimer === null) {
            pollTimer = window.setInterval(function() { poll(root); }, POLL_INTERVAL);
        }
    }

    function sendInclusion(row, checkbox) {
        var resourceid = row.getAttribute('data-resourceid');
        var included = checkbox.checked;
        checkbox.disabled = true;
        Ajax.call([{
            methodname: 'mod_tarsuszero_set_resource_inclusion',
            args: {cmid: cmid, resourceid: resourceid, included: included}
        }])[0].then(function() {
            checkbox.disabled = false;
            return null;
        }).catch(function(error) {
            checkbox.checked = !included;
            checkbox.disabled = false;
            Notification.exception(error);
        });
    }

    function sendAction(root, row, resourceid, action) {
        row.querySelectorAll(SELECTORS.ACTION_BUTTON).forEach(function(b) { b.disabled = true; });
        Ajax.call([{
            methodname: 'mod_tarsuszero_set_resource_action',
            args: {cmid: cmid, resourceid: resourceid, action: action}
        }])[0].then(function(data) {
            updateRow(row, data);
            if (data.inflight) { startPolling(root); }
            return data;
        }).catch(function(error) {
            row.querySelectorAll(SELECTORS.ACTION_BUTTON).forEach(function(b) { b.disabled = false; });
            Notification.exception(error);
        });
    }

    function handleClick(root, event) {
        var button = event.target.closest(SELECTORS.ACTION_BUTTON);
        if (!button || button.disabled) { return; }
        var row = button.closest(SELECTORS.RESOURCE_ROW);
        if (!row) { return; }
        var resourceid = row.getAttribute('data-resourceid');
        var action = button.getAttribute('data-action');
        if (action === 'remove') {
            Promise.all([
                Str.get_string('confirmremove_title', 'mod_tarsuszero'),
                Str.get_string('confirmremove_body', 'mod_tarsuszero'),
                Str.get_string('action_remove', 'mod_tarsuszero')
            ]).then(function(strings) {
                Notification.saveCancelPromise(strings[0], strings[1], strings[2])
                    .then(function() { sendAction(root, row, resourceid, action); return null; })
                    .catch(function() { return null; });
                return null;
            }).catch(Notification.exception);
            return;
        }
        sendAction(root, row, resourceid, action);
    }

    return {
        init: function(id, rootSelector) {
            cmid = id;
            var root = document.querySelector(rootSelector);
            if (!root) { return; }
            root.addEventListener('click', function(event) { handleClick(root, event); });
            root.addEventListener('change', function(event) {
                var toggle = event.target.closest(SELECTORS.INCLUDE_TOGGLE);
                if (!toggle || toggle.disabled) { return; }
                var row = toggle.closest(SELECTORS.RESOURCE_ROW);
                if (row) { sendInclusion(row, toggle); }
            });
            if (hasInflight(root)) { startPolling(root); }
        }
    };
});
